mapper.select:
SELECT o.id AS orderId, o.order_no AS orderNo, o.status AS status, o.created_at AS createdAt, a.receiver AS receiver, a.phone AS phone, CONCAT(IFNULL(a.province, ''), IFNULL(a.city, ''), IFNULL(a.district, ''), IFNULL(a.detail, '')) AS address, (SELECT SUM(oi2.price * oi2.quantity) FROM order_item oi2 JOIN product_sku ps2 ON ps2.id = oi2.sku_id JOIN product p2 ON p2.id = ps2.product_id WHERE oi2.order_id = o.id AND p2.merchant_id = #{merchantId}) AS storeAmount FROM `order` o LEFT JOIN address a ON a.id = o.address_id WHERE EXISTS (SELECT 1 FROM order_item oi JOIN product_sku ps ON ps.id = oi.sku_id JOIN product p ON p.id = ps.product_id WHERE oi.order_id = o.id AND p.merchant_id = #{merchantId})
AND o.status = #{status}
ORDER BY o.created_at DESC, o.id DESC

SELECT COUNT(*)
  FROM order_item oi
  JOIN product_sku ps ON ps.id = oi.sku_id
  JOIN product p ON p.id = ps.product_id
 WHERE oi.order_id = #{orderId}
   AND p.merchant_id = #{merchantId}
